"use client";
import { useEffect, useRef, useState } from "react";

/**
 * Nataraja rendered as a lit, displaced 3D relief (WebGL2).
 *
 * Assets (generated by scripts/build_depth.py from the cut-out):
 *  - nataraja.webp          colour + alpha
 *  - nataraja-depth.png     R = depth hi byte, B = depth lo byte (16-bit), G = ambient occlusion
 *  - nataraja-normal.webp   object-space normals (body volume + engraving micro-detail)
 *
 * Shading: baked AO, cursor-driven key light, Fresnel rim and a procedural
 * studio environment reflected off the gold so highlights travel as it turns.
 * Motion: pointer tilt, drag-to-turn with inertia, hover dolly, scroll-linked
 * camera, and a one-time materialise intro. Every motion is a damped spring.
 */

const VERT = `#version 300 es
in vec2 aPos;
uniform sampler2D uDepth;
uniform mat4 uProj, uModel;
uniform float uDepthScale, uAspect, uFlat, uZOff;
out vec2 vUv;
out vec3 vWorld;
float depthAt(vec2 uv) { vec4 d = texture(uDepth, uv); return (d.r * 65280.0 + d.b * 255.0) / 65535.0; }
void main() {
  vUv = vec2(aPos.x + 0.5, 0.5 - aPos.y);
  float d = uFlat > 0.5 ? 0.0 : depthAt(vUv);
  vec3 p = vec3(aPos.x * uAspect, aPos.y, d * uDepthScale + uZOff);
  vec4 w = uModel * vec4(p, 1.0);
  vWorld = w.xyz;
  gl_Position = uProj * w;
}`;

const FRAG = `#version 300 es
precision highp float;
uniform sampler2D uColor, uDepth, uNormal;
uniform mat3 uRot;
uniform vec3 uLight;
uniform float uReveal, uFlat, uShadowAlpha, uTime;
in vec2 vUv;
in vec3 vWorld;
out vec4 o;

vec3 env(vec3 r) {
  // simple studio: dark warm floor, soft gold horizon, two softboxes
  float h = r.y;
  vec3 c = mix(vec3(0.10, 0.03, 0.04), vec3(0.55, 0.36, 0.16), smoothstep(-0.6, 0.25, h));
  c = mix(c, vec3(0.95, 0.80, 0.55), smoothstep(0.35, 0.9, h) * 0.6);
  c += vec3(1.0, 0.88, 0.62) * smoothstep(0.82, 0.98, dot(r, normalize(vec3(-0.55, 0.45, 0.7)))) * 1.2;
  c += vec3(0.9, 0.55, 0.35) * smoothstep(0.86, 0.99, dot(r, normalize(vec3(0.7, 0.1, 0.6)))) * 0.6;
  return c;
}

void main() {
  if (uFlat > 0.5) {               // soft cast shadow on the backdrop
    float a = textureLod(uColor, vUv, 5.5).a;
    o = vec4(0.06, 0.0, 0.02, a * uShadowAlpha);
    return;
  }
  vec4 c = texture(uColor, vUv);
  // materialise: bottom-to-top dissolve with a glowing edge, broken up by the metal's own texture
  float lum = dot(c.rgb, vec3(0.299, 0.587, 0.114));
  float edge = (1.0 - vUv.y) + lum * 0.08 - uReveal * 1.25 + 0.06;
  if (edge > 0.0) discard;
  if (c.a < 0.5) discard;

  vec4 dz = texture(uDepth, vUv);
  float ao = mix(0.35, 1.0, dz.g);
  vec3 n = normalize(uRot * (texture(uNormal, vUv).rgb * 2.0 - 1.0));
  vec3 V = normalize(-vWorld);
  vec3 L = normalize(uLight);
  vec3 H = normalize(L + V);
  float ndl = max(dot(n, L), 0.0);
  float ndh = max(dot(n, H), 0.0);
  float ndv = max(dot(n, V), 0.0);
  float fres = pow(1.0 - ndv, 3.0);

  vec3 gold = c.rgb;
  vec3 R = reflect(-V, n);
  // keep the photograph's own contrast; lighting only modulates it
  vec3 col = gold * mix(0.78, 1.22, ndl) * ao;
  col += gold * env(R) * 0.38 * (0.3 + fres);                           // tinted reflection
  col += vec3(1.0, 0.9, 0.7) * pow(ndh, 120.0) * 0.9 * smoothstep(0.25, 0.8, lum);  // tight specular on raised metal
  col += gold * pow(ndh, 14.0) * 0.12;                                  // broad sheen
  col += vec3(0.9, 0.5, 0.28) * fres * 0.12 * ao;                       // faint warm rim
  col = mix(vec3(dot(col, vec3(0.299, 0.587, 0.114))), col, 0.92);      // tame saturation
  col = pow(col, vec3(1.08));                                           // slight contrast

  float glow = smoothstep(-0.05, 0.0, edge);
  col += vec3(1.0, 0.78, 0.4) * glow * 1.6;
  o = vec4(col, 1.0);
}`;

type M4 = Float32Array;
const perspective = (fov: number, aspect: number, near: number, far: number): M4 => {
  const f = 1 / Math.tan(fov / 2), nf = 1 / (near - far);
  return new Float32Array([f / aspect, 0, 0, 0, 0, f, 0, 0, 0, 0, (far + near) * nf, -1, 0, 0, 2 * far * near * nf, 0]);
};
// Rotation R = Rx(rx) * Ry(ry), column-major; returns [mat4 with translation z, mat3]
const rot = (rx: number, ry: number) => {
  const cx = Math.cos(rx), sx = Math.sin(rx), cy = Math.cos(ry), sy = Math.sin(ry);
  return [cy, sx * sy, -cx * sy, 0, cx, sx, sy, -sx * cy, cx * cy];
};
const mat4 = (r: number[], tx: number, ty: number, tz: number): M4 =>
  new Float32Array([r[0], r[1], r[2], 0, r[3], r[4], r[5], 0, r[6], r[7], r[8], 0, tx, ty, tz, 1]);

const load = (src: string) => new Promise<HTMLImageElement>((res, rej) => {
  const i = new Image(); i.decoding = "async"; i.onload = () => res(i); i.onerror = rej; i.src = src;
});

const easeOutExpo = (t: number) => (t >= 1 ? 1 : 1 - Math.pow(2, -10 * t));

export default function Statue3D({
  src, depthSrc, normalSrc, alt, hostRef,
}: { src: string; depthSrc: string; normalSrc: string; alt: string; hostRef?: React.RefObject<HTMLElement | null> }) {
  const wrap = useRef<HTMLDivElement>(null);
  const canvas = useRef<HTMLCanvasElement>(null);
  const [ready, setReady] = useState(false);
  const [fallback, setFallback] = useState(false);

  useEffect(() => {
    const cv = canvas.current!, box = wrap.current!;
    const gl = cv.getContext("webgl2", { alpha: true, antialias: true, premultipliedAlpha: false });
    if (!gl) { setFallback(true); return; }
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const amp = reduce ? 0.3 : 1;
    let disposed = false, raf = 0, visible = true;

    const compile = (type: number, s: string) => {
      const o = gl.createShader(type)!; gl.shaderSource(o, s); gl.compileShader(o);
      if (!gl.getShaderParameter(o, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(o) || "shader");
      return o;
    };
    let prog: WebGLProgram;
    try {
      prog = gl.createProgram()!;
      gl.attachShader(prog, compile(gl.VERTEX_SHADER, VERT));
      gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, FRAG));
      gl.linkProgram(prog);
      if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(prog) || "link");
    } catch (e) { console.warn(e); setFallback(true); return; }
    gl.useProgram(prog);

    // dense grid
    const SX = 260, SY = 364;
    const verts = new Float32Array((SX + 1) * (SY + 1) * 2);
    let k = 0;
    for (let y = 0; y <= SY; y++) for (let x = 0; x <= SX; x++) { verts[k++] = x / SX - 0.5; verts[k++] = 0.5 - y / SY; }
    const idx = new Uint32Array(SX * SY * 6); k = 0;
    for (let y = 0; y < SY; y++) for (let x = 0; x < SX; x++) {
      const i = y * (SX + 1) + x; idx.set([i, i + SX + 1, i + 1, i + 1, i + SX + 1, i + SX + 2], k); k += 6;
    }
    const vao = gl.createVertexArray(); gl.bindVertexArray(vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer()); gl.bufferData(gl.ARRAY_BUFFER, verts, gl.STATIC_DRAW);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, gl.createBuffer()); gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, idx, gl.STATIC_DRAW);
    const aPos = gl.getAttribLocation(prog, "aPos");
    gl.enableVertexAttribArray(aPos); gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

    const U = (n: string) => gl.getUniformLocation(prog, n);
    const u = {
      proj: U("uProj"), model: U("uModel"), rot: U("uRot"), light: U("uLight"), depthScale: U("uDepthScale"),
      aspect: U("uAspect"), flat: U("uFlat"), zoff: U("uZOff"), reveal: U("uReveal"), shadowA: U("uShadowAlpha"),
    };
    gl.uniform1i(U("uColor"), 0); gl.uniform1i(U("uDepth"), 1); gl.uniform1i(U("uNormal"), 2);

    const texture = (img: HTMLImageElement, unit: number, mip: boolean, linear = true) => {
      gl.activeTexture(gl.TEXTURE0 + unit);
      gl.bindTexture(gl.TEXTURE_2D, gl.createTexture());
      gl.pixelStorei(gl.UNPACK_COLORSPACE_CONVERSION_WEBGL, gl.NONE);
      gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
      const f = linear ? gl.LINEAR : gl.NEAREST;
      if (mip) { gl.generateMipmap(gl.TEXTURE_2D); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR); }
      else gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, f);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, f);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    };

    // ---- state ---------------------------------------------------------
    type Spring = { x: number; v: number; t: number };
    const sp = (x: number): Spring => ({ x, v: 0, t: x });
    const S = { rx: sp(0), ry: sp(0), lx: sp(-0.6), ly: sp(0.7), z: sp(0), scroll: sp(0) };
    const step = (s: Spring, k: number, d: number) => { s.v = (s.v + (s.t - s.x) * k) * d; s.x += s.v; };
    let pointer = { nx: 0, ny: 0 };
    let drag: null | { x: number; y: number; ox: number; oy: number; lastX: number; lastT: number; vel: number } = null;
    const turn = { x: 0, y: 0, vel: 0 };             // drag offset + flick inertia
    let hovering = false;
    let imgAspect = 1048 / 1468;
    let intro = 0, introStart = 0;

    const soft = (v: number, lim: number) => lim * Math.tanh(v / lim);

    const retarget = () => {
      const scroll = S.scroll.t;
      S.ry.t = pointer.nx * 0.24 * amp + soft(turn.y, 0.42) + scroll * 0.55;
      S.rx.t = pointer.ny * 0.12 * amp + soft(turn.x, 0.14) - scroll * 0.12;
      S.lx.t = Math.max(-1.3, Math.min(1.3, pointer.nx * 1.5));
      S.ly.t = Math.max(-1, Math.min(1.3, -pointer.ny * 1.5 + 0.3));
      S.z.t = (hovering ? 0.12 : 0) - scroll * 0.35;
    };

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const w = box.clientWidth, h = box.clientHeight;
      cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);
      gl.viewport(0, 0, cv.width, cv.height);
      gl.uniformMatrix4fv(u.proj, false, perspective(0.6, w / h, 0.1, 10));
      kick();
    };

    const onMove = (e: PointerEvent) => {
      const r = box.getBoundingClientRect();
      pointer = {
        nx: Math.max(-1, Math.min(1, ((e.clientX - (r.left + r.width / 2)) / window.innerWidth) * 2.2)),
        ny: Math.max(-1, Math.min(1, ((e.clientY - (r.top + r.height / 2)) / window.innerHeight) * 2.2)),
      };
      if (drag) {
        const now = performance.now();
        turn.y = drag.oy + (e.clientX - drag.x) * 0.005;
        turn.x = drag.ox + (e.clientY - drag.y) * 0.003;
        drag.vel = (e.clientX - drag.lastX) / Math.max(now - drag.lastT, 1);
        drag.lastX = e.clientX; drag.lastT = now;
      }
      retarget(); kick();
    };
    const onDown = (e: PointerEvent) => {
      drag = { x: e.clientX, y: e.clientY, ox: turn.x, oy: turn.y, lastX: e.clientX, lastT: performance.now(), vel: 0 };
      cv.setPointerCapture(e.pointerId); box.classList.add("is-dragging");
    };
    const onUp = () => {
      if (!drag) return;
      turn.vel = drag.vel * 0.06;                 // flick carries on, then eases home
      drag = null; box.classList.remove("is-dragging"); kick();
    };
    const onEnter = () => { hovering = true; retarget(); kick(); };
    const onLeave = () => { hovering = false; retarget(); kick(); };
    const onScroll = () => {
      const host = hostRef?.current; const h = host ? host.offsetHeight : window.innerHeight;
      S.scroll.t = Math.max(0, Math.min(1, window.scrollY / h));
      retarget(); kick();
    };

    let running = false;
    const kick = () => { if (!running && visible && !disposed) { running = true; raf = requestAnimationFrame(frame); } };
    const host = hostRef?.current ?? null;

    function frame(now: number) {
      if (introStart === 0) introStart = now;
      intro = reduce ? 1 : Math.min(1, (now - introStart) / 2200);

      if (!drag) {                                  // inertia then return to rest
        turn.y += turn.vel; turn.vel *= 0.9;
        if (Math.abs(turn.vel) < 0.0005) { turn.y *= 0.92; turn.x *= 0.92; }
        retarget();
      }
      const K = drag ? 0.2 : 0.06, D = drag ? 0.66 : 0.84;
      step(S.rx, K, D); step(S.ry, K, D); step(S.z, 0.05, 0.85);
      step(S.lx, 0.05, 0.85); step(S.ly, 0.05, 0.85); step(S.scroll, 0.08, 0.8);

      // intro: light sweeps in from the upper-left while the relief rises
      const e = easeOutExpo(intro);
      const lx = S.lx.x * e + -1.4 * (1 - e), ly = S.ly.x * e + 1.2 * (1 - e);

      const R = rot(S.rx.x, S.ry.x);
      const zBase = -1.9 + S.z.x;
      gl!.clearColor(0, 0, 0, 0);
      gl!.clear(gl!.COLOR_BUFFER_BIT | gl!.DEPTH_BUFFER_BIT);
      gl!.uniform1f(u.aspect, imgAspect);
      gl!.uniform3f(u.light, lx, ly, 0.8);
      gl!.uniformMatrix3fv(u.rot, false, new Float32Array(R));

      // shadow pass (flat, behind, pushed away from the light)
      gl!.disable(gl!.DEPTH_TEST);
      gl!.uniform1f(u.flat, 1);
      gl!.uniform1f(u.zoff, -0.14);
      gl!.uniform1f(u.shadowA, 0.55 * e);
      gl!.uniformMatrix4fv(u.model, false, mat4(rot(S.rx.x * 0.6, S.ry.x * 0.6), -lx * 0.05, -ly * 0.04 - 0.015, zBase));
      gl!.drawElements(gl!.TRIANGLES, idx.length, gl!.UNSIGNED_INT, 0);

      // statue
      gl!.enable(gl!.DEPTH_TEST);
      gl!.uniform1f(u.flat, 0);
      gl!.uniform1f(u.zoff, 0);
      gl!.uniform1f(u.depthScale, 0.2 * (0.25 + 0.75 * e));
      gl!.uniform1f(u.reveal, reduce ? 1 : Math.min(1, intro * 1.15));
      gl!.uniformMatrix4fv(u.model, false, mat4(R, 0, 0, zBase));
      gl!.drawElements(gl!.TRIANGLES, idx.length, gl!.UNSIGNED_INT, 0);

      if (host) {
        host.style.setProperty("--rx", S.rx.x.toFixed(4));
        host.style.setProperty("--ry", S.ry.x.toFixed(4));
        host.style.setProperty("--lx", lx.toFixed(4));
        host.style.setProperty("--ly", ly.toFixed(4));
      }
      const springs = Object.values(S);
      const moving = intro < 1 || Math.abs(turn.vel) > 0.0005 || Math.abs(turn.y) > 0.001 ||
        springs.some((s) => Math.abs(s.v) > 1e-5 || Math.abs(s.t - s.x) > 1e-4);
      if (moving && visible && !disposed) raf = requestAnimationFrame(frame); else running = false;
    }

    Promise.all([load(src), load(depthSrc), load(normalSrc)]).then(([img, dep, nrm]) => {
      if (disposed) return;
      imgAspect = img.naturalWidth / img.naturalHeight;
      texture(img, 0, true); texture(dep, 1, false, false); // NEAREST: packed 16-bit must not be interpolated texture(nrm, 2, false);
      gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
      resize(); onScroll();
      setReady(true);
    }).catch(() => setFallback(true));

    const ro = new ResizeObserver(resize); ro.observe(box);
    const io = new IntersectionObserver(([en]) => { visible = en.isIntersecting; if (visible) kick(); });
    io.observe(box);
    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("scroll", onScroll, { passive: true });
    cv.addEventListener("pointerdown", onDown);
    cv.addEventListener("pointerenter", onEnter);
    cv.addEventListener("pointerleave", onLeave);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    return () => {
      disposed = true; cancelAnimationFrame(raf); ro.disconnect(); io.disconnect();
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("scroll", onScroll);
      cv.removeEventListener("pointerdown", onDown);
      cv.removeEventListener("pointerenter", onEnter);
      cv.removeEventListener("pointerleave", onLeave);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
  }, [src, depthSrc, normalSrc, hostRef]);

  return (
    <div ref={wrap} className={`statue ${ready ? "is-ready" : ""} ${fallback ? "is-fallback" : ""}`}>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={src} alt={fallback ? alt : ""} aria-hidden={!fallback} className="statue-poster" />
      {!fallback && <canvas ref={canvas} role="img" aria-label={alt} />}
    </div>
  );
}
